// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        // Re-entrant attacker that calls setL1BlockValues again during execution
        ReentrantAttacker attacker = new ReentrantAttacker();
        // The attacker will call with a different _timestamp value to overwrite
        vm.deal(address(attacker), 0);
        // Attacker deploys a helper to call setL1BlockValues
        // Attacker's reentrant call will set timestamp to _timestamp + 1
        // But only if the original call's _timestamp != _timestamp + 1 (always true)
        // The buggy mutant places timestamp = _timestamp at the end, so the reentrant write is overwritten
        // The original places it before, so the reentrant write persists
        vm.prank(C.DEPOSITOR_ACCOUNT);
        attacker.attack(address(c), _number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);
        assertTrue(c.timestamp() == _timestamp + 1);
    }
}

contract ReentrantAttacker {
    function attack(address _c, uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        C(_c).setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);
    }

    // This receive is triggered by the target if needed, but here we call setL1BlockValues directly
    // The reentrancy happens because the attacker's attack() calls setL1BlockValues,
    // and we need a second call to setL1BlockValues during the first.
    // To achieve reentrancy, we can make the attacker's fallback call setL1BlockValues again.
    // However, the test above calls attack() which calls setL1BlockValues once.
    // For reentrancy, we need the target to call back into the attacker during setL1BlockValues.
    // But setL1BlockValues does not make external calls, so we cannot do a simple reentrant callback.
    // Instead, we exploit the fact that the attacker can call setL1BlockValues itself with a different _timestamp,
    // but only if it can get the DEPOSITOR_ACCOUNT to call it mid-execution.
    // Since the target does not call external contracts, we simulate a reentrant scenario
    // by pre-deploying a contract that will be called via a low-level call and re-enter.
    // We can modify the attack to use a fallback that calls the target again.
}

contract ReentrantHelper {
    C public target;
    constructor(C _target) { target = _target; }
    fallback() external {
        target.setL1BlockValues(0, 1, 0, bytes32(0), 0, bytes32(0), 0, 0);
    }
}

contract ActualAttacker {
    function attack(C target, uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        ReentrantHelper helper = new ReentrantHelper(target);
        // There is no external call in setL1BlockValues, so reentrancy via fallback is impossible.
        // We need a different approach.
    }
}

